public class ReferenceDemo {
    public static void main(String[] args) {

        Student s1 = new Student();
        s1.name = "Alice";
        s1.marks = 95;

        // s2 is a second reference to the SAME object — not a copy
        Student s2 = s1;

        s2.marks = 100;  // modifying through s2...

        System.out.println(s1.marks); // 100 — s1 sees the change too
        // Proof: s1 and s2 point to the same heap object

        // Null reference
        Student s3 = null;
        // s3.marks;  // NullPointerException — no object behind this reference

        // Comparing references with ==
        System.out.println(s1 == s2); // true — same object
        Student s4 = new Student();   // a brand new object
        System.out.println(s1 == s4); // false — different object, different object
    }
}

class Student {
    String name;
    int marks;
}
```

```java
public class Student {
    // Instance fields — each object gets its own copy
    String name;
    int marks;

    // Static field — one shared copy for the whole class
    static int count = 0;

    Student(String name, int marks) {
        this.name = name;
        this.marks = marks;
        count++;  // increments the shared counter every time a Student is created
    }

    // Static method — no 'this', cannot access name or marks directly
    static void printCount() {
        System.out.println("Students created: " + count);
        // System.out.println(name);  // COMPILE ERROR — which object's name?
    }
}

public class Main {
    public static void main(String[] args) {
        Student s1 = new Student("Alice", 95);
        Student s2 = new Student("Bob", 72);
        Student s3 = new Student("Carol", 88);

        System.out.println(s1.name);   // Alice — instance field, belongs to s1
        System.out.println(s2.name);   // Bob — s2's own copy

        Student.printCount();           // Students created: 3
        System.out.println(Student.count); // 3 — same value through class name
        System.out.println(s1.count);   // 3 — same shared value, just different access syntax
    }
}
